begin;
create extension if not exists pgtap with schema extensions;
select plan(42);

select has_table('review_private','reviewer_management_capabilities','reviewer management capabilities are durable');
select has_table('review_private','reviewer_capability_purge_receipts','capability purge receipts are durable');
select has_column('review_private','reviewer_credential_challenges','capability_id','credential challenges bind capabilities');
select has_column('review_private','reviewer_assertion_receipts','capability_id','verified assertions bind capabilities');
select is((select count(*) from review_private.reviewer_management_capabilities),0::bigint,'migration fabricates no management capability');
select ok((select count(*)=2 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='review_private' and c.relname in ('reviewer_management_capabilities','reviewer_capability_purge_receipts') and c.relrowsecurity and c.relforcerowsecurity),'capability tables force RLS');
select ok(not exists(select 1 from information_schema.role_table_grants where table_schema='review_private' and table_name in ('reviewer_management_capabilities','reviewer_capability_purge_receipts') and grantee in ('anon','authenticated','service_role')),'browser and generic service roles cannot read capability records');
select ok(not exists(select 1 from information_schema.columns where table_schema='review_private' and table_name='reviewer_management_capabilities' and column_name in ('token','username','email','session_id')),'raw tokens usernames and sessions are never stored');
select ok(exists(select 1 from information_schema.columns where table_schema='review_private' and table_name='reviewer_management_capabilities' and column_name='token_hash'),'only a capability token hash is durable');
select ok((select pg_get_constraintdef(oid) ilike '%30 minutes%' from pg_constraint where conrelid='review_private.reviewer_management_capabilities'::regclass and pg_get_constraintdef(oid) ilike '%expires_at%'),'capabilities expire within thirty minutes');
select ok((select pg_get_constraintdef(oid) ilike '%enrollment%management%recovery%appeal%' from pg_constraint where conrelid='review_private.reviewer_management_capabilities'::regclass and pg_get_constraintdef(oid) ilike '%scope%'),'capability scopes are constrained');
select ok(exists(select 1 from pg_trigger where tgname='reviewer_capability_purge_receipts_immutable' and not tgisinternal),'purge receipts are append-only');

select has_function('review_private','issue_reviewer_management_capability',array['uuid','text','uuid','bytea','text','timestamp with time zone','uuid'],'trusted capability issuance exists');
select has_function('app_public','reviews_request_reviewer_capability_challenge',array['text','text','uuid'],'capability challenge RPC exists');
select has_function('app_public','reviews_manage_reviewer_credentials',array['text','text','uuid','uuid'],'fresh-assertion management RPC exists');
select has_function('review_private','purge_reviewer_management_capabilities',array['timestamp with time zone','integer'],'capability lifecycle purge exists');
select ok(has_function_privilege('review_credential_capability_service','review_private.issue_reviewer_management_capability(uuid,text,uuid,bytea,text,timestamptz,uuid)','EXECUTE') and not has_function_privilege('authenticated','review_private.issue_reviewer_management_capability(uuid,text,uuid,bytea,text,timestamptz,uuid)','EXECUTE'),'only trusted service issues capabilities');
select ok(has_function_privilege('anon','app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)','EXECUTE') and not has_function_privilege('authenticated','app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)','EXECUTE'),'capability transport requires no ordinary account session');
select ok(not has_function_privilege('authenticated','app_public.reviews_request_reviewer_credential_challenge(uuid,uuid,text,uuid)','EXECUTE'),'ordinary-session identity challenge authority is removed');
select ok(not has_function_privilege('authenticated','app_public.reviews_revoke_reviewer_credential(uuid,uuid)','EXECUTE'),'ordinary-session revocation authority is removed');
select ok(has_function_privilege('review_lifecycle_service','review_private.purge_reviewer_management_capabilities(timestamptz,integer)','EXECUTE') and not has_function_privilege('authenticated','review_private.purge_reviewer_management_capabilities(timestamptz,integer)','EXECUTE'),'only lifecycle service purges capabilities');

select ok(position('p_token_hash' in lower(pg_get_functiondef('review_private.issue_reviewer_management_capability(uuid,text,uuid,bytea,text,timestamp with time zone,uuid)'::regprocedure)))>0 and position('p_capability_token' in lower(pg_get_functiondef('review_private.issue_reviewer_management_capability(uuid,text,uuid,bytea,text,timestamp with time zone,uuid)'::regprocedure)))=0,'issuer stores a hash and never receives the raw capability');
select ok(position('delivery_verification_id' in lower(pg_get_functiondef('review_private.issue_reviewer_management_capability(uuid,text,uuid,bytea,text,timestamp with time zone,uuid)'::regprocedure)))>0,'issuance requires trusted delivery verification');
select ok(position('reviewer_capability_idempotency_reused' in lower(pg_get_functiondef('review_private.issue_reviewer_management_capability(uuid,text,uuid,bytea,text,timestamp with time zone,uuid)'::regprocedure)))>0,'issuance replays exactly and rejects key reuse');
select ok(position($q$digest(convert_to(p_capability_token,'utf8'),'sha256')$q$ in replace(lower(pg_get_functiondef('app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)'::regprocedure)),' ',''))>0,'raw capability is hashed for constant lookup');
select ok(position('for update' in lower(pg_get_functiondef('app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)'::regprocedure)))>0 and position($q$state<>'active'$q$ in replace(lower(pg_get_functiondef('app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)'::regprocedure)),' ',''))>0,'challenge issuance locks and rechecks one-use state');
select ok(position($q$cap.scope not in ('enrollment','recovery')$q$ in lower(pg_get_functiondef('app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)'::regprocedure)))>0 and position($q$cap.scope not in ('management','appeal')$q$ in lower(pg_get_functiondef('app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)'::regprocedure)))>0,'ceremonies enforce exact capability scopes');
select ok(position('registration_completed_count>=cap.registration_target_count' in replace(lower(pg_get_functiondef('app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)'::regprocedure)),' ',''))>0 and position($q$i.state not in ('pending','active','disabled')$q$ in lower(pg_get_functiondef('app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)'::regprocedure)))>0,'setup and recovery admit exactly the unfinished two-credential target');
select ok(position('auth.uid()' in lower(pg_get_functiondef('app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)'::regprocedure)))=0 and position('username' in lower(pg_get_functiondef('app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)'::regprocedure)))=0,'challenge authority never uses username or normal-session identity lookup');
select ok(position($q$message='reviewer_credential_unavailable'$q$ in replace(lower(pg_get_functiondef('app_public.reviews_request_reviewer_capability_challenge(text,text,uuid)'::regprocedure)),' ',''))>0,'invalid capability errors are reason neutral');
select ok(exists(select 1 from pg_trigger where tgname='reviewer_registration_consume_capability' and not tgisinternal),'successful registration consumes enrollment or recovery capability');
select ok(exists(select 1 from pg_trigger where tgname='reviewer_assertion_bind_capability' and not tgisinternal) and exists(select 1 from pg_trigger where tgname='reviewer_assertion_consume_capability' and not tgisinternal),'fresh assertions bind and consume their capability');
select ok(position($q$cap.scope<>'management'$q$ in replace(lower(pg_get_functiondef('app_public.reviews_manage_reviewer_credentials(text,text,uuid,uuid)'::regprocedure)),' ',''))>0 and position('reviewer_assertion_receipts' in lower(pg_get_functiondef('app_public.reviews_manage_reviewer_credentials(text,text,uuid,uuid)'::regprocedure)))>0,'list and revoke require management scope plus fresh verified assertion');
select ok(position('where idempotency_key=p_idempotency_key' in lower(pg_get_functiondef('app_public.reviews_manage_reviewer_credentials(text,text,uuid,uuid)'::regprocedure)))>0 and position('return prior.result' in lower(pg_get_functiondef('app_public.reviews_manage_reviewer_credentials(text,text,uuid,uuid)'::regprocedure)))>0,'lost management responses replay their exact result');
select ok(position('for update' in lower(pg_get_functiondef('app_public.reviews_manage_reviewer_credentials(text,text,uuid,uuid)'::regprocedure)))>0,'concurrent capability use serializes on the capability row');
select ok(position('retire_reviewer_credential' in lower(pg_get_functiondef('app_public.reviews_manage_reviewer_credentials(text,text,uuid,uuid)'::regprocedure)))>0 and position('cnt>=2' in replace(lower(pg_get_functiondef('app_public.reviews_manage_reviewer_credentials(text,text,uuid,uuid)'::regprocedure)),' ',''))>0,'revocation deletes authority material and preserves the two-credential threshold');
select ok(position($q$interval '24 hours'$q$ in lower(pg_get_functiondef('review_private.purge_reviewer_management_capabilities(timestamp with time zone,integer)'::regprocedure)))>0 and position('token_hash=null' in replace(lower(pg_get_functiondef('review_private.purge_reviewer_management_capabilities(timestamp with time zone,integer)'::regprocedure)),' ',''))>0,'expired capability hashes purge after the approved window');
select ok(position('delete from review_private.reviewer_credential_challenges' in lower(pg_get_functiondef('review_private.purge_reviewer_management_capabilities(timestamp with time zone,integer)'::regprocedure)))>0,'consumed and expired challenges delete after the approved window');
select ok(position('i.user_id is null or i.relationship_ended_at is not null' in lower(pg_get_functiondef('review_private.purge_reviewer_management_capabilities(timestamp with time zone,integer)'::regprocedure)))>0,'account or reviewer relationship end revokes management authority');
select ok(position('for update skip locked' in lower(pg_get_functiondef('review_private.purge_reviewer_management_capabilities(timestamp with time zone,integer)'::regprocedure)))>0,'concurrent lifecycle sweeps use skip-locked claims');
select ok(position($q$set state='revoked',revoked_at=statement_timestamp()$q$ in replace(lower(pg_get_functiondef('review_private.revoke_reviewer_verifier(text)'::regprocedure)),' ',''))>0 and position('reviewer_management_capabilities' in lower(pg_get_functiondef('review_private.revoke_reviewer_verifier(text)'::regprocedure)))>0,'verifier revocation also revokes live capabilities');
select ok(position('purge_reviewer_management_capabilities' in lower(pg_get_functiondef('app_public.run_due_review_lifecycle(timestamp with time zone,integer)'::regprocedure)))>0,'scheduled review lifecycle includes capability expiry and purge');

select * from finish();
rollback;
